func (v *ShortTextType) UnmarshalJSON(src []byte) error {
	var value string
	err := json.Unmarshal(src, &value)
	if err != nil {
		return err
	}
	enumTypeValue := ShortTextType(value)
	for _, existing := range AllowedShortTextTypeEnumValues {
		if existing == enumTypeValue {
			*v = enumTypeValue
			return nil
		}
	}

	return fmt.Errorf("%+v is not a valid ShortTextType", value)
}

// NewShortTextTypeFromValue returns a pointer to a valid ShortTextType
// for the value passed as argument, or an error if the value passed is not allowed by the enum
func NewShortTextTypeFromValue(v string) (*ShortTextType, error) {
	ev := ShortTextType(v)
	if ev.IsValid() {
		return &ev, nil
	} else {
		return nil, fmt.Errorf("invalid value '%v' for ShortTextType: valid values are %v", v, AllowedShortTextTypeEnumValues)
	}
}

// IsValid return true if the value is valid for the enum, false otherwise
func (v ShortTextType) IsValid() bool {
	for _, existing := range AllowedShortTextTypeEnumValues {
		if existing == v {
			return true
		}
	}
	return false
}

